import {AIRPORTS,STALE_SECONDS} from './flight-data.js';
const $=s=>document.querySelector(s);const section=$('#flight-map-section');
let map,rangeRing,airportPin,planeLayer,activeAirport='JFK',radius=100,rows=[],selectedId=null,feedTime=null,lastFetched=null,visible=false,paused=false,requestId=0,controller=null,nextRefresh=0,loading=false,lastError=false,limit=35;
const airports=Object.values(AIRPORTS);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const label=a=>a.callsign||a.registration||a.id.toUpperCase();const num=n=>n===null?'Unknown':Math.round(n).toLocaleString('en-US');const altitude=a=>a.onGround?'On ground':a.altitudeFt===null?'Unknown':`${num(a.altitudeFt)} ft`;const age=a=>Math.max(0,Math.round(Date.now()/1000-a.positionTime));const fresh=a=>age(a)<=STALE_SECONDS;
function setStatus(message,state=''){ $('#feed-state').textContent=message;$('#feed-dot').className='feed-dot '+state; }
airports.forEach((a,i)=>{const b=document.createElement('button');b.className='airport-tab';b.role='tab';b.id=`airport-${a.code}`;b.setAttribute('aria-controls','airport-panel');b.setAttribute('aria-selected',String(a.code===activeAirport));b.tabIndex=a.code===activeAirport?0:-1;b.innerHTML=`<b>${a.code}</b><span>${esc(a.city)}</span>`;b.addEventListener('click',()=>chooseAirport(a.code));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%6;if(e.key==='ArrowLeft')n=(i+5)%6;if(e.key==='Home')n=0;if(e.key==='End')n=5;if(n!==undefined){e.preventDefault();chooseAirport(airports[n].code);$('#airport-'+airports[n].code).focus();}});$('#airport-tabs').append(b)});
function updateAirportControls(){airports.forEach(a=>{const b=$('#airport-'+a.code);b.setAttribute('aria-selected',String(a.code===activeAirport));b.tabIndex=a.code===activeAirport?0:-1});$('#airport-panel').setAttribute('aria-labelledby',`airport-${activeAirport}`);$('#map-airport-name').textContent=`${AIRPORTS[activeAirport].city} / ${activeAirport}`;$('#map-radius-label').textContent=`${radius} nautical mile coverage area`;}
function chooseAirport(code){if(code===activeAirport)return;activeAirport=code;resetData();updateAirportControls();if(map){placeAirport();loadFlights();}else init();}
function resetData(){controller?.abort();requestId++;rows=[];selectedId=null;feedTime=null;lastFetched=null;limit=35;loading=false;nextRefresh=0;lastError=false;$('#flight-error').hidden=true;$('#flight-selection').hidden=true;$('#flight-search').value='';setStatus('Connecting…');render();}
function placeAirport(){const a=AIRPORTS[activeAirport];if(rangeRing)map.removeLayer(rangeRing);if(airportPin)map.removeLayer(airportPin);rangeRing=L.circle([a.lat,a.lon],{radius:radius*1852,color:'#8aaedd',weight:1,opacity:.7,fillColor:'#426ba4',fillOpacity:.04,dashArray:'5,7',interactive:false}).addTo(map);airportPin=L.marker([a.lat,a.lon],{icon:L.divIcon({className:'airport-pin',html:activeAirport,iconSize:[42,27],iconAnchor:[21,13]}),keyboard:false,interactive:false}).addTo(map);map.fitBounds(rangeRing.getBounds(),{padding:[25,25],animate:false});}
function init(){if(map)return;if(!window.L){setStatus('Map library unavailable','warning');$('#flight-error').hidden=false;$('#flight-error').textContent='The map could not load. Refresh the page to try again.';return;}
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 map=L.map('flight-map',{center:[AIRPORTS[activeAirport].lat,AIRPORTS[activeAirport].lon],zoom:7,scrollWheelZoom:false,zoomControl:false,preferCanvas:true,minZoom:2,maxZoom:16,zoomAnimation:!reduced,fadeAnimation:!reduced,markerZoomAnimation:!reduced});L.control.zoom({position:'topright'}).addTo(map);L.control.scale({position:'bottomright',imperial:true,metric:false}).addTo(map);
 const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',updateWhenIdle:true,keepBuffer:1});let failures=0;tiles.on('tileerror',()=>{if(++failures>=3)$('#map-tile-error').hidden=false});tiles.on('tileload',()=>{failures=0;$('#map-tile-error').hidden=true});tiles.addTo(map);
 const AircraftLayer=L.Layer.extend({onAdd(m){this._map=m;this.canvas=L.DomUtil.create('canvas','flight-canvas');this.canvas.setAttribute('aria-hidden','true');m.getPanes().overlayPane.appendChild(this.canvas);this.redraw=this.redraw.bind(this);m.on('move zoom resize viewreset',this.redraw);this.redraw();},onRemove(m){m.off('move zoom resize viewreset',this.redraw);this.canvas.remove();},redraw(){if(this.scheduled)return;this.scheduled=requestAnimationFrame(()=>{this.scheduled=null;this.draw()});},draw(){if(!this._map||!this.canvas)return;const m=this._map,size=m.getSize(),dpr=Math.min(devicePixelRatio||1,2);this.canvas.width=size.x*dpr;this.canvas.height=size.y*dpr;this.canvas.style.width=size.x+'px';this.canvas.style.height=size.y+'px';L.DomUtil.setPosition(this.canvas,m.containerPointToLayerPoint([0,0]));const c=this.canvas.getContext('2d');c.scale(dpr,dpr);this.points=[];const bounds=m.getBounds().pad(.05);for(const a of filtered()){if(!bounds.contains([a.lat,a.lon]))continue;const p=m.latLngToContainerPoint([a.lat,a.lon]);this.points.push({a,x:p.x,y:p.y});const stale=!fresh(a)||lastError;c.save();c.translate(p.x,p.y);c.rotate((a.heading||0)*Math.PI/180);c.scale(a.id===selectedId?1.05:.8,a.id===selectedId?1.05:.8);c.globalAlpha=stale?.4:1;c.fillStyle=a.id===selectedId?'#ffffff':(a.onGround||a.altitudeFt===null)?'#aab4c2':a.altitudeFt!==null&&a.altitudeFt<10000?'#62dfbe':'#92b8ff';c.strokeStyle='#102039';c.lineWidth=1.2;c.beginPath();if(a.onGround||a.heading===null){c.arc(0,0,4,0,Math.PI*2);}else{c.moveTo(0,-9);c.lineTo(2,-3);c.lineTo(8,2);c.lineTo(8,4);c.lineTo(2,2);c.lineTo(2,6);c.lineTo(4,8);c.lineTo(4,9);c.lineTo(0,7);c.lineTo(-4,9);c.lineTo(-4,8);c.lineTo(-2,6);c.lineTo(-2,2);c.lineTo(-8,4);c.lineTo(-8,2);c.lineTo(-2,-3);c.closePath();}c.fill();c.stroke();c.restore();if(a.id===selectedId){c.beginPath();c.strokeStyle='#fff';c.lineWidth=1;c.arc(p.x,p.y,15,0,Math.PI*2);c.stroke();}}}});
 planeLayer=new AircraftLayer().addTo(map);map.on('click',e=>{let nearest=null,best=19;for(const p of planeLayer.points||[]){const d=Math.hypot(p.x-e.containerPoint.x,p.y-e.containerPoint.y);if(d<best){nearest=p.a;best=d;}}if(nearest)selectFlight(nearest.id);});placeAirport();updateAirportControls();new ResizeObserver(()=>map.invalidateSize()).observe($('#flight-map'));loadFlights();}
function filtered(){const query=$('#flight-search').value.trim().toLowerCase(),filter=$('#flight-filter').value;return rows.filter(a=>(!query||[a.callsign,a.registration,a.aircraftType,a.id].some(x=>x.toLowerCase().includes(query)))&&(filter==='all'||(filter==='ground'?a.onGround===true:a.onGround===false)));}
function selection(){const a=rows.find(x=>x.id===selectedId);const el=$('#flight-selection');if(!a){el.hidden=true;return;}el.hidden=false;el.className='flight-selection';el.innerHTML=`<button class="close-flight" aria-label="Close flight details">×</button><h4>${esc(label(a))}</h4><p class="flight-identity">${esc(a.registration||'Registration unknown')} · ${esc(a.aircraftType||'Type unknown')}</p><dl><div><dt>ALTITUDE</dt><dd>${altitude(a)}</dd></div><div><dt>GROUND SPEED</dt><dd>${a.groundspeedKt===null?'Unknown':num(a.groundspeedKt)+' kt'}</dd></div><div><dt>HEADING</dt><dd>${a.heading===null?'Unknown':Math.round(a.heading)+'°'}</dd></div><div><dt>DISTANCE FROM ${activeAirport}</dt><dd>${a.distanceNm} NM</dd></div><div><dt>LATITUDE</dt><dd>${a.lat.toFixed(4)}°</dd></div><div><dt>LONGITUDE</dt><dd>${a.lon.toFixed(4)}°</dd></div></dl><p class="observation-age">${fresh(a)&&!lastError?'Position observed':'Last known position'} ${age(a)}s ago · ${esc(a.id.toUpperCase())}</p>`;el.querySelector('button').onclick=()=>{selectedId=null;el.hidden=true;render();};}
function selectFlight(id){selectedId=id;selection();planeLayer?.redraw();renderList();}
function renderList(){const visibleRows=filtered();const list=$('#flight-list');const focused=document.activeElement?.dataset?.flight;const top=list.scrollTop;list.replaceChildren();if(!visibleRows.length){const p=document.createElement('p');p.className='map-empty';p.textContent=loading?'Connecting to the live aircraft feed…':lastError?'Live data is unavailable. Use Refresh to try again.':rows.length?'No aircraft match this search or filter.':lastFetched?'No recent aircraft positions were reported in this area. Coverage may be limited.':'Waiting for live observations…';list.append(p);}else for(const a of visibleRows.slice(0,limit)){const b=document.createElement('button');b.type='button';b.className='flight-row'+(a.id===selectedId?' selected':'');b.dataset.flight=a.id;b.setAttribute('aria-label',`${label(a)}, ${altitude(a)}, ${a.distanceNm} nautical miles away`);b.setAttribute('aria-pressed',String(a.id===selectedId));b.innerHTML=`<strong>${esc(label(a))}</strong><span>${altitude(a)}</span><small>${esc(a.aircraftType||a.registration||a.id)}</small><small>${a.distanceNm} NM${fresh(a)&&!lastError?'':' · stale'}</small>`;b.onclick=()=>{selectFlight(a.id);if(!map.getBounds().contains([a.lat,a.lon]))map.panTo([a.lat,a.lon]);};list.append(b);}$('#flight-more').hidden=visibleRows.length<=limit;$('#flight-more').textContent=`Show more (${Math.min(limit,visibleRows.length)} of ${visibleRows.length})`;list.scrollTop=top;if(focused)list.querySelector(`[data-flight="${CSS.escape(focused)}"]`)?.focus({preventScroll:true});$('#flight-count').textContent=rows.length?rows.length.toLocaleString():lastFetched?'0':'—';$('#flight-coverage').textContent=visibleRows.length===rows.length?'Reported in this area':`${visibleRows.length} matching filter`;}
function render(){renderList();selection();planeLayer?.redraw();}
function clockStatus(){const chosen=rows.find(a=>a.id===selectedId);const ageLabel=$('.observation-age');if(chosen&&ageLabel)ageLabel.textContent=`${fresh(chosen)&&!lastError?'Position observed':'Last known position'} ${age(chosen)}s ago · ${chosen.id.toUpperCase()}`;if(loading)return;if(paused){setStatus('Updates paused','warning');}else if(lastError){setStatus('Feed unavailable','warning');}else if(feedTime&&Date.now()/1000-feedTime>STALE_SECONDS){setStatus('Observations are stale','warning');}else if(feedTime){setStatus('Live observations','live');}$('#feed-time').textContent=feedTime?`Feed ${new Date(feedTime*1000).toLocaleTimeString('en-GB',{hour12:false,timeZone:'UTC'})} UTC · ${paused?'paused':'15s refresh'}`:'Updates every 15 seconds while visible';}
async function loadFlights(){if(loading||document.hidden||!visible)return;const remaining=nextRefresh-Date.now();if(remaining>0)return;controller?.abort();controller=new AbortController();const activeController=controller;const id=++requestId,code=activeAirport,requestedRadius=radius;loading=true;setStatus('Updating observations…');$('#flight-refresh').disabled=true;if(!rows.length)renderList();const timeout=setTimeout(()=>activeController.abort(),22000);
 try{const r=await fetch(`/api/flight-map?airport=${code}&radius=${requestedRadius}`,{signal:activeController.signal,cache:'no-store'});const body=await r.json();if(id!==requestId)return;if(!r.ok){nextRefresh=Date.now()+Math.max(30,Math.min(3600,Number(body.retrySeconds)||30))*1000;throw new Error(body.error||'The live flight feed is unavailable.');}if(body.airport!==code||body.radiusNm!==requestedRadius||!Array.isArray(body.rows)||!Number.isFinite(body.feedTime))throw new Error('The flight service returned an invalid observation set.');rows=body.rows;feedTime=body.feedTime;lastFetched=body.fetchedAt;lastError=false;nextRefresh=Date.now()+15000;$('#flight-error').hidden=true;render();}
 catch(e){if(id!==requestId)return;lastError=true;nextRefresh=Math.max(nextRefresh,Date.now()+30000);$('#flight-error').textContent=(e.name==='AbortError'?'The flight request timed out.':e.message)+(rows.length?' Showing dimmed last-known positions; these are not current.':' No simulated aircraft have been substituted.');$('#flight-error').hidden=false;render();}
 finally{clearTimeout(timeout);if(id===requestId){loading=false;$('#flight-refresh').disabled=false;render();clockStatus();}}
}
$('#flight-radius').onchange=e=>{radius=Number(e.target.value);resetData();updateAirportControls();if(map){placeAirport();loadFlights();}};
$('#flight-search').oninput=()=>{limit=35;render();};$('#flight-filter').onchange=()=>{limit=35;render();};$('#flight-more').onclick=()=>{limit+=35;renderList();};
$('#flight-refresh').onclick=()=>{if(Date.now()<nextRefresh){setStatus(`Refresh available in ${Math.ceil((nextRefresh-Date.now())/1000)}s`,lastError?'warning':'');return;}if(!map)init();else loadFlights();};
$('#flight-pause').onclick=()=>{paused=!paused;$('#flight-pause').setAttribute('aria-pressed',String(paused));$('#flight-pause').textContent=paused?'Resume updates':'Pause updates';clockStatus();if(!paused)loadFlights();};
const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible){if(!map)init();else{map.invalidateSize();if(!paused)loadFlights();}}},{threshold:0});observer.observe(section);
const ticker=setInterval(()=>{clockStatus();if(visible&&!document.hidden){planeLayer?.redraw();if(!paused&&Date.now()>=nextRefresh)loadFlights();}},1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&visible&&!paused)loadFlights();});window.addEventListener('pagehide',e=>{if(!e.persisted){controller?.abort();clearInterval(ticker);observer.disconnect();}});updateAirportControls();
